","/* ═══════════════════════════════════════════════════════════════════════
 Industrial Supply Co. — Customer Portal Stylesheet
 Includes shared design-system tokens + portal-specific layout.
 ═══════════════════════════════════════════════════════════════════════ */

:root {
 /* ── Brand ────────────────────────────────────── */
 --ids-brand-navy: #0f2438;
 --ids-brand-navy-light: #1a3a5c;
 --ids-brand-accent: #2563eb;
 --ids-brand-accent-hover:#1d4ed8;

 /* ── Backgrounds ──────────────────────────────── */
 --ids-bg-page: #f1f5f9;
 --ids-bg-card: #ffffff;
 --ids-bg-surface: #f8fafc;
 --ids-bg-hover: #f1f5f9;
 --ids-bg-active: #e2e8f0;

 /* ── Text ─────────────────────────────────────── */
 --ids-text-primary: #0f172a;
 --ids-text-secondary: #475569;
 --ids-text-tertiary: #94a3b8;
 --ids-text-inverse: #ffffff;
 --ids-text-link: #2563eb;

 /* ── Borders ──────────────────────────────────── */
 --ids-border: #e2e8f0;
 --ids-border-light: #f1f5f9;
 --ids-border-focus: #2563eb;

 /* ── Status / Semantic ────────────────────────── */
 --ids-success: #16a34a;
 --ids-success-bg: rgba(22,163,74,.08);
 --ids-warning: #d97706;
 --ids-warning-bg: rgba(217,119,6,.08);
 --ids-error: #dc2626;
 --ids-error-bg: rgba(220,38,38,.06);
 --ids-info: #0284c7;
 --ids-info-bg: rgba(2,132,199,.08);

 /* ── Spacing ──────────────────────────────────── */
 --ids-sp-1: 4px; --ids-sp-2: 8px; --ids-sp-3: 12px;
 --ids-sp-4: 16px; --ids-sp-5: 20px; --ids-sp-6: 24px;
 --ids-sp-8: 32px; --ids-sp-10: 40px; --ids-sp-12: 48px;

 /* ── Radius ───────────────────────────────────── */
 --ids-radius-sm: 6px;
 --ids-radius-md: 10px;
 --ids-radius-lg: 16px;
 --ids-radius-full: 9999px;

 /* ── Shadows ──────────────────────────────────── */
 --ids-shadow-sm: 0 1px 2px rgba(0,0,0,.05);
 --ids-shadow-md: 0 2px 8px rgba(0,0,0,.08);
 --ids-shadow-lg: 0 4px 16px rgba(0,0,0,.1);

 /* ── Typography ───────────────────────────────── */
 --ids-font: "Source Sans Pro", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
 --ids-font-mono: "SF Mono", "Fira Code", "Fira Mono", Menlo, monospace;
 --ids-text-xs: 11px;
 --ids-text-sm: 13px;
 --ids-text-md: 14px;
 --ids-text-lg: 16px;
 --ids-text-xl: 20px;
 --ids-text-2xl: 24px;
 --ids-text-3xl: 28px;
}

/* ── Global Reset ───────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; }
html, body { margin: 0; padding: 0; height: 100%; overflow: hidden; }
body { font-family: var(--ids-font); color: var(--ids-text-primary); background: var(--ids-bg-page); }

/* ── Scrollbar ──────────────────────────────────── */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 3px; }
::-webkit-scrollbar-track { background: transparent; }

/* ═══════════════════════════════════════════════════
 SHARED UTILITY CLASSES (from design system)
 ═══════════════════════════════════════════════════ */

.ids-card {
 background: var(--ids-bg-card); border-radius: var(--ids-radius-md);
 border: 1px solid var(--ids-border); padding: var(--ids-sp-6);
 box-shadow: var(--ids-shadow-sm);
}
.ids-card-title {
 margin: 0 0 var(--ids-sp-4) 0; font-size: 15px; font-weight: 700;
 color: var(--ids-text-primary); letter-spacing: .01em;
}

.ids-badge {
 display: inline-flex; align-items: center; justify-content: center;
 padding: 2px 10px; border-radius: var(--ids-radius-full);
 font-size: var(--ids-text-xs); font-weight: 700;
 text-transform: capitalize; letter-spacing: .02em; white-space: nowrap;
}
.ids-badge-info { background: var(--ids-info-bg); color: var(--ids-info); }
.ids-badge-success { background: var(--ids-success-bg); color: var(--ids-success); }
.ids-badge-warning { background: var(--ids-warning-bg); color: var(--ids-warning); }
.ids-badge-error { background: var(--ids-error-bg); color: var(--ids-error); }

.ids-btn {
 display: inline-flex; align-items: center; justify-content: center; gap: 8px;
 padding: 8px 16px; border-radius: var(--ids-radius-sm);
 font-size: var(--ids-text-sm); font-weight: 600; font-family: var(--ids-font);
 cursor: pointer; border: 1px solid transparent;
 transition: background .15s, color .15s, border-color .15s, box-shadow .15s;
}
.ids-btn:focus-visible { outline: 2px solid var(--ids-border-focus); outline-offset: 2px; }
.ids-btn-primary {
 background: var(--ids-brand-navy); color: var(--ids-text-inverse); border-color: var(--ids-brand-navy);
}
.ids-btn-primary:hover { background: var(--ids-brand-navy-light); }
.ids-btn-accent {
 background: var(--ids-brand-accent); color: var(--ids-text-inverse); border-color: var(--ids-brand-accent);
}
.ids-btn-accent:hover { background: var(--ids-brand-accent-hover); }
.ids-btn-ghost {
 background: transparent; color: var(--ids-brand-accent); border-color: var(--ids-border);
}
.ids-btn-ghost:hover { background: var(--ids-bg-hover); }
.ids-btn-danger { background: var(--ids-error); color: #fff; border-color: var(--ids-error); }
.ids-btn-link {
 background: none; border: none; color: var(--ids-text-link);
 padding: 0; font-size: 12.5px; font-weight: 600; cursor: pointer; font-family: var(--ids-font);
}
.ids-btn-link:hover { text-decoration: underline; }

.ids-table { width: 100%; border-collapse: collapse; }
.ids-table th {
 padding: 10px 14px; font-size: var(--ids-text-xs); font-weight: 700;
 text-transform: uppercase; letter-spacing: .05em;
 color: var(--ids-text-tertiary); text-align: left;
 border-bottom: 2px solid var(--ids-border); background: var(--ids-bg-surface);
}
.ids-table td {
 padding: 12px 14px; font-size: var(--ids-text-sm); color: var(--ids-text-primary);
 border-bottom: 1px solid var(--ids-border-light); vertical-align: middle;
}
.ids-table tr:hover td { background: var(--ids-bg-surface); }

.ids-kpi {
 background: var(--ids-bg-card); border-radius: var(--ids-radius-md);
 border: 1px solid var(--ids-border); padding: 20px 16px;
 display: flex; flex-direction: column; align-items: center; gap: 6px;
 text-align: center; box-shadow: var(--ids-shadow-sm);
}
.ids-kpi-value { font-size: var(--ids-text-3xl); font-weight: 700; line-height: 1.1; }
.ids-kpi-label {
 font-size: var(--ids-text-xs); font-weight: 600; color: var(--ids-text-tertiary);
 text-transform: uppercase; letter-spacing: .06em;
}

.ids-empty {
 display: flex; flex-direction: column; align-items: center; justify-content: center;
 padding: 48px 32px; gap: 12px; text-align: center;
}
.ids-empty-icon {
 width: 56px; height: 56px; border-radius: var(--ids-radius-lg);
 background: var(--ids-bg-surface); display: flex; align-items: center;
 justify-content: center; color: var(--ids-text-tertiary); font-size: 24px;
}
.ids-empty-title { font-size: var(--ids-text-lg); font-weight: 600; color: var(--ids-text-primary); }
.ids-empty-desc { font-size: var(--ids-text-sm); color: var(--ids-text-tertiary); max-width: 380px; }

@keyframes ids-spin { to { transform: rotate(360deg); } }
.ids-spinner {
 width: 28px; height: 28px;
 border: 3px solid var(--ids-border);
 border-top-color: var(--ids-brand-navy);
 border-radius: 50%;
 animation: ids-spin .8s linear infinite;
}

.ids-grid-4 { display: grid; grid-template-columns: repeat(4,1fr); gap: 16px; }
.ids-grid-3 { display: grid; grid-template-columns: repeat(3,1fr); gap: 16px; }
.ids-grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }

/* ═══════════════════════════════════════════════════
 PORTAL LAYOUT — Header, Nav Tabs, Content
 ═══════════════════════════════════════════════════ */

.portal-shell {
 display: flex; flex-direction: column; height: 100vh; width: 100%;
 font-family: var(--ids-font); background: var(--ids-bg-page);
}

/* ── Header ─────────────────────────────────────── */
.portal-header {
 background: var(--ids-brand-navy); color: var(--ids-text-inverse);
 flex-shrink: 0;
}
.portal-header-top {
 display: flex; align-items: center; justify-content: space-between;
 padding: 0 32px; height: 56px;
}
.portal-brand {
 font-size: 17px; font-weight: 700; letter-spacing: .01em;
 display: flex; align-items: center; gap: 10px;
}
.portal-brand-icon {
 width: 28px; height: 28px; border-radius: 6px;
 background: rgba(255,255,255,.15); display: flex;
 align-items: center; justify-content: center; font-size: 14px;
}
.portal-header-right {
 display: flex; align-items: center; gap: 20px;
}
.portal-customer-name {
 font-size: 13px; opacity: .8; font-weight: 500;
}
.portal-cart-btn {
 background: rgba(255,255,255,.12); border: none; color: #fff;
 padding: 6px 12px; border-radius: var(--ids-radius-sm);
 cursor: pointer; font-family: var(--ids-font); font-size: 13px;
 font-weight: 600; display: flex; align-items: center; gap: 6px;
 transition: background .15s;
 position: relative;
}
.portal-cart-btn:hover { background: rgba(255,255,255,.2); }
.portal-cart-badge {
 position: absolute; top: -6px; right: -6px;
 min-width: 18px; height: 18px; padding: 0 5px;
 border-radius: 9px; background: var(--ids-brand-accent);
 color: #fff; font-size: 10px; font-weight: 700;
 display: flex; align-items: center; justify-content: center;
}

/* ── Nav Tabs ───────────────────────────────────── */
.portal-nav {
 display: flex; align-items: center; gap: 2px;
 padding: 0 32px; background: rgba(0,0,0,.15);
 overflow-x: auto;
}
.portal-tab {
 padding: 10px 16px; font-size: 13px; font-weight: 500;
 color: rgba(255,255,255,.65); background: none; border: none;
 border-bottom: 2px solid transparent; cursor: pointer;
 white-space: nowrap; font-family: var(--ids-font);
 transition: color .15s, border-color .15s;
}
.portal-tab:hover { color: rgba(255,255,255,.9); }
.portal-tab-active {
 color: #fff; font-weight: 600;
 border-bottom-color: var(--ids-brand-accent);
}

/* ── Content ────────────────────────────────────── */
.portal-content {
 flex: 1; overflow-y: auto; padding: 28px 32px;
}
.portal-section {
 max-width: 1200px; margin: 0 auto;
}

/* ═══════════════════════════════════════════════════
 PORTAL SECTIONS
 ═══════════════════════════════════════════════════ */

/* ── Section Header ─────────────────────────────── */
.section-header {
 margin-bottom: 24px;
}
.section-title {
 margin: 0; font-size: var(--ids-text-2xl); font-weight: 700;
 color: var(--ids-brand-navy);
}
.section-subtitle {
 margin: 6px 0 0; font-size: var(--ids-text-md); color: var(--ids-text-secondary);
}

/* ── Product Grid / Cards ───────────────────────── */
.product-grid {
 display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 20px;
}
.product-card {
 background: var(--ids-bg-card); border: 1px solid var(--ids-border);
 border-radius: var(--ids-radius-md); box-shadow: var(--ids-shadow-sm);
 overflow: hidden; transition: box-shadow .2s, transform .15s; cursor: default;
 display: flex; flex-direction: column;
}
.product-card:hover { box-shadow: var(--ids-shadow-md); transform: translateY(-2px); }
.product-card-header {
 padding: 16px 20px 12px; border-bottom: 1px solid var(--ids-border-light);
 display: flex; justify-content: space-between; align-items: flex-start;
}
.product-card-body { padding: 16px 20px; flex: 1; display: flex; flex-direction: column; }
.product-card-name { font-size: 15px; font-weight: 700; color: var(--ids-text-primary); margin: 0 0 6px; }
.product-card-desc {
 font-size: var(--ids-text-sm); color: var(--ids-text-secondary); line-height: 1.5;
 display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
 margin: 0 0 12px; flex: 1;
}
.product-card-footer {
 padding: 12px 20px; border-top: 1px solid var(--ids-border-light);
 display: flex; justify-content: space-between; align-items: center;
}
.product-price { font-size: 17px; font-weight: 700; color: var(--ids-brand-navy); }
.product-uom { font-size: var(--ids-text-xs); color: var(--ids-text-tertiary); margin-left: 4px; }

/* ── Product Detail ─────────────────────────────── */
.product-detail { display: grid; grid-template-columns: 1fr 360px; gap: 24px; }
.pricing-card {
 background: var(--ids-bg-card); border: 1px solid var(--ids-border);
 border-radius: var(--ids-radius-md); padding: 24px; box-shadow: var(--ids-shadow-sm);
 position: sticky; top: 0; align-self: start;
}
.pricing-row {
 display: flex; justify-content: space-between; align-items: center;
 padding: 10px 0; border-bottom: 1px solid var(--ids-border-light);
}
.pricing-total {
 display: flex; justify-content: space-between; align-items: center;
 padding: 14px 0 0; font-size: 18px; font-weight: 700; color: var(--ids-brand-navy);
}

/* ── Cart ───────────────────────────────────────── */
.cart-item {
 display: flex; align-items: center; gap: 16px;
 padding: 16px 0; border-bottom: 1px solid var(--ids-border-light);
}
.cart-item-info { flex: 1; }
.cart-item-name { font-size: 14px; font-weight: 600; color: var(--ids-text-primary); }
.cart-item-meta { font-size: 12px; color: var(--ids-text-tertiary); margin-top: 2px; }
.cart-controls {
 display: flex; align-items: center; gap: 0;
 border: 1px solid var(--ids-border); border-radius: var(--ids-radius-sm); overflow: hidden;
}
.cart-qty-btn {
 width: 32px; height: 32px; border: none; background: var(--ids-bg-surface);
 cursor: pointer; font-size: 16px; font-weight: 600; color: var(--ids-text-primary);
 display: flex; align-items: center; justify-content: center;
 font-family: var(--ids-font); transition: background .12s;
}
.cart-qty-btn:hover { background: var(--ids-bg-hover); }
.cart-qty-display {
 width: 40px; text-align: center; font-size: 14px; font-weight: 600;
 font-family: var(--ids-font-mono); border-left: 1px solid var(--ids-border);
 border-right: 1px solid var(--ids-border); line-height: 32px;
}
.cart-item-price { font-size: 14px; font-weight: 700; color: var(--ids-brand-navy); width: 90px; text-align: right; }
.cart-remove {
 background: none; border: none; color: var(--ids-text-tertiary);
 cursor: pointer; font-size: 18px; padding: 4px; transition: color .12s;
}
.cart-remove:hover { color: var(--ids-error); }
.cart-footer {
 display: flex; justify-content: space-between; align-items: center;
 padding: 20px 0 0; margin-top: 8px; border-top: 2px solid var(--ids-border);
}
.cart-total { font-size: 20px; font-weight: 700; color: var(--ids-brand-navy); }
.cart-actions { display: flex; gap: 10px; }

/* ── Order Review Form ──────────────────────────── */
.order-form { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-top: 20px; }
.order-form-field { display: flex; flex-direction: column; gap: 6px; }
.order-form-field.full { grid-column: 1 / -1; }
.order-form-label {
 font-size: var(--ids-text-xs); font-weight: 700; color: var(--ids-text-tertiary);
 text-transform: uppercase; letter-spacing: .04em;
}
.order-form-input {
 padding: 10px 14px; border: 1px solid var(--ids-border); border-radius: var(--ids-radius-sm);
 font-size: var(--ids-text-md); font-family: var(--ids-font); color: var(--ids-text-primary);
 background: var(--ids-bg-card); transition: border-color .15s;
}
.order-form-input:focus { outline: none; border-color: var(--ids-border-focus); box-shadow: 0 0 0 3px rgba(37,99,235,.1); }
textarea.order-form-input { min-height: 80px; resize: vertical; }

/* ── Filter Pills ───────────────────────────────── */
.filter-pills { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 20px; }
.filter-pill {
 padding: 6px 14px; border-radius: var(--ids-radius-full);
 font-size: var(--ids-text-xs); font-weight: 600; cursor: pointer;
 border: 1px solid var(--ids-border); background: var(--ids-bg-card);
 color: var(--ids-text-secondary); font-family: var(--ids-font);
 transition: all .15s;
}
.filter-pill:hover { background: var(--ids-bg-hover); border-color: var(--ids-brand-accent); }
.filter-pill-active {
 background: var(--ids-brand-accent); color: #fff;
 border-color: var(--ids-brand-accent);
}

/* ── Status Badges ──────────────────────────────── */
.status-badge {
 display: inline-flex; align-items: center; padding: 2px 10px;
 border-radius: var(--ids-radius-full); font-size: var(--ids-text-xs);
 font-weight: 700; text-transform: capitalize; letter-spacing: .02em;
}
.status-draft { background: #f1f5f9; color: #64748b; }
.status-submitted { background: var(--ids-info-bg); color: var(--ids-info); }
.status-approved { background: var(--ids-success-bg); color: var(--ids-success); }
.status-in_production{ background: var(--ids-warning-bg); color: var(--ids-warning); }
.status-completed { background: rgba(22,163,74,.12); color: #15803d; }
.status-cancelled { background: var(--ids-error-bg); color: var(--ids-error); }

/* ── Delivery ───────────────────────────────────── */
.delivery-list { display: flex; flex-direction: column; gap: 12px; }
.delivery-card {
 background: var(--ids-bg-card); border: 1px solid var(--ids-border);
 border-radius: var(--ids-radius-md); padding: 20px 24px;
 display: flex; align-items: center; justify-content: space-between;
 box-shadow: var(--ids-shadow-sm);
}
.countdown { font-size: 14px; font-weight: 700; }
.countdown-ok { color: var(--ids-success); }
.countdown-soon { color: var(--ids-warning); }
.countdown-overdue { color: var(--ids-error); }

/* ── Profile ────────────────────────────────────── */
.profile-grid {
 display: grid; grid-template-columns: 1fr 1fr; gap: 16px;
}
.profile-field {
 padding: 14px 18px; border-radius: var(--ids-radius-sm);
 background: var(--ids-bg-surface); border: 1px solid var(--ids-border-light);
}
.profile-label {
 font-size: var(--ids-text-xs); font-weight: 700; color: var(--ids-text-tertiary);
 text-transform: uppercase; letter-spacing: .04em; margin-bottom: 4px;
}
.profile-value { font-size: var(--ids-text-md); font-weight: 500; color: var(--ids-text-primary); }

/* ── Surveys ────────────────────────────────────── */
.rating-stars { display: flex; gap: 6px; margin-bottom: 16px; }
.star-btn {
 width: 40px; height: 40px; border: 1px solid var(--ids-border);
 border-radius: var(--ids-radius-sm); background: var(--ids-bg-card);
 cursor: pointer; font-size: 20px; display: flex; align-items: center;
 justify-content: center; transition: all .15s;
}
.star-btn:hover { border-color: var(--ids-warning); background: var(--ids-warning-bg); }
.star-btn-filled {
 background: var(--ids-warning-bg); border-color: var(--ids-warning); color: var(--ids-warning);
}

/* ── Search ─────────────────────────────────────── */
.search-bar {
 display: flex; align-items: center; gap: 10px;
 margin-bottom: 20px; position: relative;
}
.search-input {
 width: 100%; max-width: 400px; padding: 10px 14px 10px 38px;
 border: 1px solid var(--ids-border); border-radius: var(--ids-radius-sm);
 font-size: var(--ids-text-md); font-family: var(--ids-font);
 color: var(--ids-text-primary); background: var(--ids-bg-card);
 transition: border-color .15s;
}
.search-input:focus { outline: none; border-color: var(--ids-border-focus); box-shadow: 0 0 0 3px rgba(37,99,235,.1); }
.search-icon {
 position: absolute; left: 12px; top: 50%; transform: translateY(-50%);
 color: var(--ids-text-tertiary); pointer-events: none; font-size: 14px;
}

/* ── Qty Input (Product Detail) ─────────────────── */
.qty-input {
 width: 80px; padding: 8px 12px; border: 1px solid var(--ids-border);
 border-radius: var(--ids-radius-sm); font-size: var(--ids-text-md);
 font-family: var(--ids-font-mono); text-align: center;
 color: var(--ids-text-primary); background: var(--ids-bg-card);
}
.qty-input:focus { outline: none; border-color: var(--ids-border-focus); }

/* ── Success State ──────────────────────────────── */
.success-state {
 display: flex; flex-direction: column; align-items: center;
 padding: 60px 32px; text-align: center; gap: 16px;
}
.success-icon {
 width: 64px; height: 64px; border-radius: 50%;
