","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","import React, { useState, useEffect, useCallback } from "react";
import ReactDOM from "react-dom/client";
import "./portal.css";

/* ═══════════════════ CONSTANTS ═══════════════════ */
const SCOPE = "x_2056099_indust_0";
const API = {
 context: `/api/${SCOPE}/customer_context_api/context`,
 products: `/api/now/table/${SCOPE}_mat_master?sysparm_display_value=all&sysparm_limit=200&sysparm_query=active=true&sysparm_fields=sys_id,material_name,material_product_id,category,description,unit_of_measure,standard_cost,safety_stock`,
 postOrder: `/api/now/table/${SCOPE}_cust_order`,
 postOrderItem: `/api/now/table/${SCOPE}_cust_ord_item`,
};
function buildOrdersUrl(id: string) { return `/api/now/table/${SCOPE}_cust_order?sysparm_display_value=all&sysparm_limit=200&sysparm_query=customer=${id}^ORDERBYDESCorder_date`; }
function buildItemsUrl(id: string) { return `/api/now/table/${SCOPE}_cust_ord_item?sysparm_display_value=all&sysparm_limit=500&sysparm_query=customer_order.customer=${id}`; }

interface CustCtx { linked: boolean; customer?: CustData; userEmail?: string; message?: string; }
interface CustData { sys_id: string; customer_name: string; customer_id: string; primary_contact_email: string; primary_contact_phone: string; customer_type: string; payment_terms: string; credit_limit: string; industry: string; notes: string; }

type Rec = Record<string, any>;
interface CartItem { productId: string; productName: string; quantity: number; uom: string; unitPrice: number; }

const NAV_TABS = [
 { key: "dashboard", label: "Dashboard" },
 { key: "catalog", label: "Catalog" },
 { key: "orders", label: "My Orders" },
 { key: "delivery", label: "Delivery" },
 { key: "demand", label: "Demand" },
 { key: "surveys", label: "Surveys" },
 { key: "profile", label: "Profile" },
];

const STATUS_FILTERS = ["All", "Draft", "Submitted", "Approved", "In Production", "Completed", "Cancelled"];

/* ═══════════════════ HELPERS ═══════════════════ */
function tk(): string { return (window as any).g_ck || ""; }

const hdrs = (): Record<string, string> => ({ Accept: "application/json", "X-UserToken": tk() });

async function apiFetch<T>(url: string): Promise<T | null> {
 try {
 const r = await fetch(url, { headers: hdrs() });
 if (!r.ok) return null;
 const j = await r.json();
 return (j?.result ?? null) as T | null;
 } catch { return null; }
}

async function apiPost(url: string, body: any): Promise<any> {
 try {
 const r = await fetch(url, {
 method: "POST",
 headers: { ...hdrs(), "Content-Type": "application/json" },
 body: JSON.stringify(body),
 });
 if (!r.ok) return null;
 return await r.json();
 } catch { return null; }
}

function dv(f: any): string {
 if (!f) return "";
 if (typeof f === "string") return f;
 return f.display_value || f.value || "";
}
function val(f: any): string {
 if (!f) return "";
 if (typeof f === "string") return f;
 return f.value || f.display_value || "";
}
function fmtDate(d: string): string {
 if (!d) return "—";
 try { return new Date(d).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" }); } catch { return d; }
}
function fmtCurrency(v: number): string {
 return "$" + v.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}
function parsePrice(f: any): number {
 const s = dv(f).replace(/[^0-9.]/g, "");
 return parseFloat(s) || 0;
}
function statusClass(s: string): string {
 const k = s.toLowerCase().replace(/\s+/g, "_");
 return `status-badge status-${k}`;
}
function statusLabel(s: string): string {
 return s.replace(/_/g, " ");
}
function daysUntil(dateStr: string): number {
 if (!dateStr) return 0;
 const d = new Date(dateStr);
 const now = new Date();
 now.setHours(0, 0, 0, 0);
 d.setHours(0, 0, 0, 0);
 return Math.ceil((d.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
}

/* ═══════════════════ ROUTE PARSING ═══════════════════ */
interface Route { view: string; id?: string; }
function parseHash(): Route {
 const h = window.location.hash.replace("#", "");
 if (!h) return { view: "dashboard" };
 const parts = h.split("&");
 const view = parts[0] || "dashboard";
 let id: string | undefined;
 for (let i = 1; i < parts.length; i++) {
 const [k, v] = parts[i].split("=");
 if (k === "id") id = v;
 }
 return { view, id };
}
function setHash(view: string, id?: string) {
 window.location.hash = id ? `${view}&id=${id}` : view;
}

/* ═══════════════════ SHARED COMPONENTS ═══════════════════ */
function Loading({ msg }: { msg?: string }) {
