}

function EmptyState({ icon, title, desc }: { icon: string; title: string; desc?: string }) {
 return (
 <div className="ids-empty">
 <div className="ids-empty-icon">{icon}</div>
 <div className="ids-empty-title">{title}</div>
 {desc && <div className="ids-empty-desc">{desc}</div>}
 </div>
 );
}

function SectionHeader({ title, sub, children }: { title: string; sub?: string; children?: React.ReactNode }) {
 return (
