/* ═══════════════════ DASHBOARD ═══════════════════ */
function Dashboard({ orders, orderItems, products, navigate }: {
 orders: Rec[]; orderItems: Rec[]; products: Rec[]; navigate: (v: string, id?: string) => void;
}) {
 const total = orders.length;
 const active = orders.filter(o => {
 const s = val(o.status).toLowerCase();
 return s !== "completed" && s !== "cancelled";
 });
 const inProd = orders.filter(o => val(o.status).toLowerCase() === "in_production" || dv(o.status).toLowerCase() === "in production");
 const delivered = orders.filter(o => val(o.status).toLowerCase() === "completed" || val(o.status).toLowerCase() === "delivered");

 /* Next Delivery */
 const now = new Date();
 now.setHours(0, 0, 0, 0);
 let nextDelivery: Rec | null = null;
 let nextDays = Infinity;
 for (const o of active) {
 const dd = val(o.requested_delivery_date);
 if (!dd) continue;
 const d = daysUntil(dd);
 if (d >= 0 && d < nextDays) { nextDays = d; nextDelivery = o; }
 }

 /* Best Selling Products */
 const cancelledOrderIds = new Set(
 orders.filter(o => val(o.status).toLowerCase() === "cancelled").map(o => val(o.sys_id))
 );
 const productQty: Record<string, { name: string; qty: number }> = {};
 for (const item of orderItems) {
 const orderId = val(item.customer_order);
 if (cancelledOrderIds.has(orderId)) continue;
 const pName = dv(item.material_product) || "Unknown";
 const qty = parseInt(dv(item.quantity_ordered) || "0", 10) || 0;
 if (!productQty[pName]) productQty[pName] = { name: pName, qty: 0 };
 productQty[pName].qty += qty;
 }
 const bestSellers = Object.values(productQty).sort((a, b) => b.qty - a.qty).slice(0, 5);
 const maxQty = bestSellers.length > 0 ? bestSellers[0].qty : 1;

 return (
 <div className="portal-section">
 <SectionHeader title="Dashboard" sub="Overview of your orders and activity" />

 {/* KPI Strip */}
 <div className="ids-grid-4" style={{ marginBottom: 20 }}>
 <KpiCard value={total} label="Total Orders" color="var(--ids-brand-navy)" border="var(--ids-brand-navy)" />
 <KpiCard value={active.length} label="Active Orders" color="var(--ids-info)" border="var(--ids-info)" />
 <KpiCard value={inProd.length} label="In Production" color="var(--ids-warning)" border="var(--ids-warning)" />
 <KpiCard value={delivered.length} label="Delivered / Completed" color="var(--ids-success)" border="var(--ids-success)" />
 </div>

 {/* Current Orders + Next Delivery */}
 <div className="ids-grid-2" style={{ marginBottom: 20 }}>
 <div className="ids-card">
 <h3 className="ids-card-title">Current Orders</h3>
 {active.length === 0 ? (
 <EmptyState icon="📦" title="No active orders" desc="Place an order from the catalog to get started." />
 ) : (
 <div>
 {active.slice(0, 3).map((o, i) => (
 <div key={i} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "10px 0", borderBottom: i < 2 ? "1px solid var(--ids-border-light)" : "none" }}>
 <div>
 <div style={{ fontSize: 14, fontWeight: 600, color: "var(--ids-text-link)", cursor: "pointer" }}
 onClick={() => navigate("order", val(o.sys_id))}>{dv(o.number)}</div>
 <div style={{ fontSize: 12, color: "var(--ids-text-tertiary)" }}>{fmtDate(dv(o.order_date))}</div>
 </div>
 <StatusBadge status={val(o.status)} />
 </div>
 ))}
 {active.length > 3 && (
 <button className="ids-btn-link" style={{ marginTop: 12 }} onClick={() => navigate("orders")}>
 View all {active.length} active orders →
 </button>
 )}
 </div>
 )}
 </div>

 <div className="ids-card">
 <h3 className="ids-card-title">Next Delivery</h3>
 {nextDelivery ? (
 <div style={{ display: "flex", flexDirection: "column", alignItems: "center", padding: "20px 0", gap: 8 }}>
 <div style={{ fontSize: 40, fontWeight: 700, color: "var(--ids-brand-navy)" }}>
 {nextDays === 0 ? "Today" : `${nextDays}d`}
 </div>
 <div style={{ fontSize: 13, color: "var(--ids-text-secondary)" }}>
 {nextDays === 0 ? "Delivery expected today" : `${nextDays} day${nextDays !== 1 ? "s" : ""} until delivery`}
 </div>
 <div style={{ fontSize: 14, fontWeight: 600, color: "var(--ids-text-link)", cursor: "pointer", marginTop: 4 }}
 onClick={() => navigate("order", val(nextDelivery!.sys_id))}>
 {dv(nextDelivery.number)}
 </div>
 <div style={{ fontSize: 12, color: "var(--ids-text-tertiary)" }}>
 Delivery: {fmtDate(dv(nextDelivery.requested_delivery_date))}
 </div>
 </div>
 ) : (
 <EmptyState icon="🚚" title="No upcoming deliveries" desc="Active orders with delivery dates will appear here." />
 )}
 </div>
 </div>

 {/* Best Selling Products */}
 <div className="ids-card">
 <h3 className="ids-card-title">Best Selling Products</h3>
 {bestSellers.length === 0 ? (
 <EmptyState icon="📊" title="No order data yet" desc="Product rankings will appear once orders are placed." />
 ) : (
 <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
 {bestSellers.map((p, i) => (
 <div key={i} style={{ display: "flex", alignItems: "center", gap: 14 }}>
 <span style={{ width: 22, fontSize: 13, fontWeight: 700, color: "var(--ids-text-tertiary)", textAlign: "right" }}>#{i + 1}</span>
 <div style={{ flex: 1 }}>
 <div style={{ fontSize: 13, fontWeight: 600 }}>{p.name}</div>
 <div style={{ height: 6, borderRadius: 3, background: "var(--ids-bg-surface)", marginTop: 4, overflow: "hidden" }}>
 <div style={{ height: "100%", borderRadius: 3, background: "var(--ids-brand-accent)", width: `${(p.qty / maxQty) * 100}%`, transition: "width .4s" }} />
 </div>
 </div>
 <span style={{ fontSize: 14, fontWeight: 700, fontFamily: "var(--ids-font-mono)", color: "var(--ids-brand-navy)", minWidth: 50, textAlign: "right" }}>{p.qty}</span>
 </div>
 ))}
 </div>
 )}
 </div>
 </div>
 );
}

/* ═══════════════════ CATALOG ═══════════════════ */
function Catalog({ products, navigate }: { products: Rec[]; navigate: (v: string, id?: string) => void }) {
 const [search, setSearch] = useState("");
 const filtered = products.filter(p => {
 const name = dv(p.material_name).toLowerCase();
 return name.includes(search.toLowerCase());
 });

 return (
 <div className="portal-section">
 <SectionHeader title="Product Catalog" sub={`${products.length} products available`} />
 <div className="search-bar">
 <span className="search-icon">🔍</span>
 <input className="search-input" placeholder="Search products by name…"
 value={search} onChange={e => setSearch(e.target.value)} />
 </div>
 {filtered.length === 0 ? (
 <div className="ids-card">
 <EmptyState icon="🔍" title="No products found" desc={search ? "Try adjusting your search." : "No products are available."} />
 </div>
 ) : (
 <div className="product-grid">
 {filtered.map((p, i) => {
 const price = parsePrice(p.standard_cost);
 return (
 <div className="product-card" key={i}>
 <div className="product-card-header">
 <span className="ids-badge ids-badge-info">{dv(p.category) || "General"}</span>
 {dv(p.material_product_id) && <span style={{ fontSize: 11, color: "var(--ids-text-tertiary)", fontFamily: "var(--ids-font-mono)" }}>{dv(p.material_product_id)}</span>}
 </div>
 <div className="product-card-body">
 <div className="product-card-name">{dv(p.material_name)}</div>
 <p className="product-card-desc">{dv(p.description) || "No description available."}</p>
 </div>
 <div className="product-card-footer">
 <div>
 <span className="product-price">{price > 0 ? fmtCurrency(price) : "—"}</span>
 <span className="product-uom">/ {dv(p.unit_of_measure) || "ea"}</span>
 </div>
 <button className="ids-btn ids-btn-accent" onClick={() => navigate("product", val(p.sys_id))}>
 View Details
 </button>
 </div>
 </div>
 );
 })}
 </div>
 )}
 </div>
 );
}

/* ═══════════════════ PRODUCT DETAIL ═══════════════════ */
function ProductDetail({ productId, products, addToCart, navigate }: {
 productId: string; products: Rec[];
 addToCart: (item: CartItem) => void; navigate: (v: string, id?: string) => void;
}) {
 const product = products.find(p => val(p.sys_id) === productId);
 const [qty, setQty] = useState("1");
 const [added, setAdded] = useState(false);

 if (!product) return (
 <div className="portal-section">
 <div className="ids-card"><EmptyState icon="❓" title="Product not found" desc="This product may no longer be available." /></div>
 </div>
 );

 const price = parsePrice(product.standard_cost);
 const qtyNum = parseInt(qty, 10);
 const validQty = !isNaN(qtyNum) && qtyNum > 0 && Number.isInteger(qtyNum);
 const lineTotal = validQty ? price * qtyNum : 0;
 const uom = dv(product.unit_of_measure) || "ea";

 const handleAdd = () => {
 if (!validQty) return;
 addToCart({
 productId: val(product.sys_id),
 productName: dv(product.material_name),
 quantity: qtyNum,
 uom,
 unitPrice: price,
 });
 setAdded(true);
 setTimeout(() => setAdded(false), 2000);
 };

 return (
 <div className="portal-section">
 <button className="ids-btn ids-btn-ghost" style={{ marginBottom: 20 }} onClick={() => navigate("catalog")}>
 ← Back to Catalog
 </button>
 <div className="product-detail">
 {/* Left: Product Info */}
 <div>
 <div className="ids-card">
 <div style={{ display: "flex", gap: 12, marginBottom: 16 }}>
 <span className="ids-badge ids-badge-info">{dv(product.category) || "General"}</span>
 {dv(product.material_product_id) && <span style={{ fontSize: 12, fontFamily: "var(--ids-font-mono)", color: "var(--ids-text-tertiary)" }}>{dv(product.material_product_id)}</span>}
 </div>
 <h2 style={{ margin: "0 0 12px", fontSize: 22, fontWeight: 700, color: "var(--ids-brand-navy)" }}>{dv(product.material_name)}</h2>
 <p style={{ fontSize: 14, color: "var(--ids-text-secondary)", lineHeight: 1.6, margin: 0 }}>
 {dv(product.description) || "No description available for this product."}
 </p>
 {dv(product.safety_stock) && (
 <div style={{ marginTop: 16, padding: "12px 16px", background: "var(--ids-bg-surface)", borderRadius: "var(--ids-radius-sm)", fontSize: 13, color: "var(--ids-text-secondary)" }}>
 Safety Stock Level: <strong>{dv(product.safety_stock)}</strong>
 </div>
 )}
 </div>
 </div>

 {/* Right: Pricing Card */}
 <div className="pricing-card">
 <h3 style={{ margin: "0 0 16px", fontSize: 16, fontWeight: 700 }}>Pricing</h3>
 <div className="pricing-row">
 <span style={{ fontSize: 13, color: "var(--ids-text-secondary)" }}>Unit Price</span>
 <span style={{ fontSize: 16, fontWeight: 700, color: "var(--ids-brand-navy)" }}>{price > 0 ? fmtCurrency(price) : "—"}</span>
 </div>
 <div className="pricing-row">
 <span style={{ fontSize: 13, color: "var(--ids-text-secondary)" }}>UOM</span>
 <span style={{ fontSize: 14, fontWeight: 600 }}>{uom}</span>
 </div>
 <div className="pricing-row">
 <span style={{ fontSize: 13, color: "var(--ids-text-secondary)" }}>Quantity</span>
 <input className="qty-input" type="number" min="1" step="1"
 value={qty} onChange={e => setQty(e.target.value)} />
 </div>
 {!validQty && qty !== "" && (
 <div style={{ fontSize: 12, color: "var(--ids-error)", marginTop: 6 }}>Enter a positive whole number.</div>
 )}
 <div className="pricing-total">
 <span>Line Total</span>
 <span>{fmtCurrency(lineTotal)}</span>
 </div>
 <button className="ids-btn ids-btn-accent" style={{ width: "100%", marginTop: 20, padding: "12px 16px" }}
 onClick={handleAdd} disabled={!validQty || price === 0}>
 {added ? "✓ Added to Cart" : "Add to Cart"}
 </button>
 </div>
 </div>
 </div>
 );
}

/* ═══════════════════ CART VIEW ═══════════════════ */
function CartView({ cart, updateQty, removeItem, navigate }: {
 cart: CartItem[]; updateQty: (i: number, q: number) => void;
 removeItem: (i: number) => void; navigate: (v: string, id?: string) => void;
}) {
 const total = cart.reduce((sum, c) => sum + c.unitPrice * c.quantity, 0);

 return (
 <div className="portal-section">
 <SectionHeader title="Shopping Cart" sub={`${cart.length} item${cart.length !== 1 ? "s" : ""} in cart`} />
 {cart.length === 0 ? (
 <div className="ids-card">
 <EmptyState icon="🛒" title="Your cart is empty" desc="Browse the catalog to add products." />
 <div style={{ textAlign: "center", marginTop: 8 }}>
 <button className="ids-btn ids-btn-accent" onClick={() => navigate("catalog")}>Browse Catalog</button>
 </div>
 </div>
 ) : (
 <div className="ids-card">
 {cart.map((item, i) => (
 <div className="cart-item" key={i}>
 <div className="cart-item-info">
 <div className="cart-item-name">{item.productName}</div>
 <div className="cart-item-meta">{fmtCurrency(item.unitPrice)} / {item.uom}</div>
 </div>
 <div className="cart-controls">
 <button className="cart-qty-btn" onClick={() => updateQty(i, Math.max(1, item.quantity - 1))}>−</button>
 <div className="cart-qty-display">{item.quantity}</div>
 <button className="cart-qty-btn" onClick={() => updateQty(i, item.quantity + 1)}>+</button>
 </div>
 <div className="cart-item-price">{fmtCurrency(item.unitPrice * item.quantity)}</div>
 <button className="cart-remove" onClick={() => removeItem(i)} title="Remove">✕</button>
 </div>
 ))}
 <div className="cart-footer">
 <div className="cart-total">Total: {fmtCurrency(total)}</div>
 <div className="cart-actions">
 <button className="ids-btn ids-btn-ghost" onClick={() => navigate("catalog")}>Continue Shopping</button>
 <button className="ids-btn ids-btn-accent" onClick={() => navigate("review")}>Review Order</button>
 </div>
 </div>
 </div>
 )}
 </div>
 );
}

/* ═══════════════════ ORDER REVIEW & SUBMIT ═══════════════════ */
function OrderReview({ cart, customer, clearCart, navigate }: {
 cart: CartItem[]; customer: Rec | null;
 clearCart: () => void; navigate: (v: string, id?: string) => void;
}) {
 const [deliveryDate, setDeliveryDate] = useState("");
 const [location, setLocation] = useState("");
 const [instructions, setInstructions] = useState("");
 const [submitting, setSubmitting] = useState(false);
 const [submitted, setSubmitted] = useState(false);
 const [orderNum, setOrderNum] = useState("");

 const total = cart.reduce((s, c) => s + c.unitPrice * c.quantity, 0);
 const totalQty = cart.reduce((s, c) => s + c.quantity, 0);

 const handleSubmit = async () => {
 if (!customer || !val(customer.sys_id)) return;
 setSubmitting(true);
 const custId = val(customer.sys_id);
 const orderBody: Rec = {
 customer: custId,
 status: "submitted",
 total_order_quantity: totalQty,
 };
 if (deliveryDate) orderBody.requested_delivery_date = deliveryDate;
 if (location) orderBody.delivery_location = location;
 if (instructions) orderBody.special_instructions = instructions;

 const orderRes = await apiPost(API.postOrder, orderBody);
 if (!orderRes?.result) { setSubmitting(false); return; }

 const orderId = val(orderRes.result.sys_id);
 const num = dv(orderRes.result.number);
 setOrderNum(num);

 for (const item of cart) {
 await apiPost(API.postOrderItem, {
 customer_order: orderId,
 material_product: item.productId,
 quantity_ordered: item.quantity,
 unit_of_measure: item.uom,
 });
 }

 clearCart();
 setSubmitting(false);
 setSubmitted(true);
 };

 if (submitted) {
 return (
 <div className="portal-section">
 <div className="ids-card">
 <div className="success-state">
 <div className="success-icon">✓</div>
 <div className="success-title">Order Submitted!</div>
 <div className="success-desc">
 Your order {orderNum && <strong>{orderNum}</strong>} has been submitted successfully. You can track its progress in My Orders.
 </div>
 <div style={{ display: "flex", gap: 10, marginTop: 12 }}>
 <button className="ids-btn ids-btn-ghost" onClick={() => navigate("orders")}>View My Orders</button>
 <button className="ids-btn ids-btn-accent" onClick={() => navigate("catalog")}>Continue Shopping</button>
 </div>
 </div>
 </div>
 </div>
 );
 }

 if (cart.length === 0) {
 return (
 <div className="portal-section">
 <div className="ids-card">
 <EmptyState icon="📋" title="No items to review" desc="Add products to your cart first." />
 </div>
 </div>
 );
 }

 return (
 <div className="portal-section">
 <SectionHeader title="Review Order" sub="Confirm your order details before submitting" />
 <button className="ids-btn ids-btn-ghost" style={{ marginBottom: 20 }} onClick={() => navigate("cart")}>← Back to Cart</button>

 {/* Items Summary */}
 <div className="ids-card" style={{ marginBottom: 20 }}>
 <h3 className="ids-card-title">Order Items</h3>
 <div style={{ overflowX: "auto" }}>
 <table className="ids-table">
 <thead><tr><th>Product</th><th>Qty</th><th>UOM</th><th>Unit Price</th><th>Total</th></tr></thead>
 <tbody>
 {cart.map((item, i) => (
 <tr key={i}>
 <td style={{ fontWeight: 600 }}>{item.productName}</td>
 <td style={{ fontFamily: "var(--ids-font-mono)" }}>{item.quantity}</td>
 <td>{item.uom}</td>
 <td>{fmtCurrency(item.unitPrice)}</td>
 <td style={{ fontWeight: 700, color: "var(--ids-brand-navy)" }}>{fmtCurrency(item.unitPrice * item.quantity)}</td>
 </tr>
 ))}
 </tbody>
 </table>
 </div>
 <div style={{ textAlign: "right", padding: "14px 14px 0", fontSize: 18, fontWeight: 700, color: "var(--ids-brand-navy)" }}>
 Order Total: {fmtCurrency(total)} ({totalQty} items)
 </div>
 </div>

 {/* Order Form */}
 <div className="ids-card">
 <h3 className="ids-card-title">Delivery Details</h3>
 <div className="order-form">
 <div className="order-form-field">
 <label className="order-form-label">Requested Delivery Date</label>
 <input className="order-form-input" type="date" value={deliveryDate} onChange={e => setDeliveryDate(e.target.value)} />
 </div>
 <div className="order-form-field">
 <label className="order-form-label">Delivery Location</label>
 <input className="order-form-input" type="text" placeholder="e.g. Warehouse B, Dock 3" value={location} onChange={e => setLocation(e.target.value)} />
 </div>
 <div className="order-form-field full">
 <label className="order-form-label">Special Instructions</label>
 <textarea className="order-form-input" placeholder="Any special handling or delivery requirements…" value={instructions} onChange={e => setInstructions(e.target.value)} />
 </div>
 </div>
 <div style={{ display: "flex", justifyContent: "flex-end", gap: 10, marginTop: 24 }}>
 <button className="ids-btn ids-btn-ghost" onClick={() => navigate("cart")}>Back to Cart</button>
 <button className="ids-btn ids-btn-accent" style={{ padding: "10px 28px" }} onClick={handleSubmit} disabled={submitting}>
 {submitting ? "Submitting…" : "Submit Order"}
 </button>
 </div>
 </div>
 </div>
 );
}

/* ═══════════════════ MY ORDERS ═══════════════════ */
function MyOrders({ orders, navigate }: { orders: Rec[]; navigate: (v: string, id?: string) => void }) {
 const [filter, setFilter] = useState("All");

 const filtered = filter === "All" ? orders : orders.filter(o => {
 const sv = dv(o.status).toLowerCase();
 const fv = filter.toLowerCase().replace(/\s+/g, "_");
 return sv === fv || val(o.status).toLowerCase() === fv || sv === filter.toLowerCase();
 });

 return (
 <div className="portal-section">
 <SectionHeader title="My Orders" sub={`${orders.length} total orders`} />
 <div className="filter-pills">
 {STATUS_FILTERS.map(f => (
 <button key={f} className={`filter-pill${filter === f ? " filter-pill-active" : ""}`} onClick={() => setFilter(f)}>
 {f}
 </button>
 ))}
 </div>
 {filtered.length === 0 ? (
 <div className="ids-card">
 <EmptyState icon="📦" title={`No ${filter.toLowerCase()} orders`} desc="Orders matching this filter will appear here." />
 </div>
 ) : (
 <div className="ids-card" style={{ padding: 0, overflow: "hidden" }}>
 <div style={{ overflowX: "auto" }}>
 <table className="ids-table">
 <thead>
 <tr><th>Number</th><th>Date</th><th>Delivery Date</th><th>Type</th><th>Priority</th><th>Status</th><th>Total Qty</th><th>Reference</th></tr>
 </thead>
 <tbody>
 {filtered.map((o, i) => (
 <tr key={i} style={{ cursor: "pointer" }} onClick={() => navigate("order", val(o.sys_id))}>
 <td style={{ fontWeight: 600, color: "var(--ids-text-link)" }}>{dv(o.number)}</td>
 <td style={{ whiteSpace: "nowrap" }}>{fmtDate(dv(o.order_date))}</td>
 <td style={{ whiteSpace: "nowrap" }}>{dv(o.requested_delivery_date) ? fmtDate(dv(o.requested_delivery_date)) : "—"}</td>
 <td>{dv(o.order_type) || "—"}</td>
 <td>{dv(o.priority) || "—"}</td>
 <td><StatusBadge status={val(o.status)} /></td>
 <td style={{ fontFamily: "var(--ids-font-mono)" }}>{dv(o.total_order_quantity) || "—"}</td>
 <td>{dv(o.customer_reference) || "—"}</td>
 </tr>
 ))}
 </tbody>
 </table>
 </div>
 </div>
 )}
 </div>
 );
}

/* ═══════════════════ ORDER DETAIL ═══════════════════ */
function OrderDetail({ orderId, orders, orderItems, navigate }: {
 orderId: string; orders: Rec[]; orderItems: Rec[]; navigate: (v: string, id?: string) => void;
}) {
 const order = orders.find(o => val(o.sys_id) === orderId);
 if (!order) return (
 <div className="portal-section">
 <div className="ids-card"><EmptyState icon="❓" title="Order not found" /></div>
 </div>
 );

 const items = orderItems.filter(it => val(it.customer_order) === orderId);

 const fields: [string, string][] = [
 ["Number", dv(order.number)],
 ["Status", ""],
 ["Order Date", fmtDate(dv(order.order_date))],
 ["Requested Delivery", dv(order.requested_delivery_date) ? fmtDate(dv(order.requested_delivery_date)) : "—"],
 ["Order Type", dv(order.order_type) || "—"],
 ["Priority", dv(order.priority) || "—"],
 ["Total Quantity", dv(order.total_order_quantity) || "—"],
 ["Customer Reference", dv(order.customer_reference) || "—"],
 ["Delivery Location", dv(order.delivery_location) || "—"],
 ["Special Instructions", dv(order.special_instructions) || "—"],
 ];

 return (
 <div className="portal-section">
 <button className="ids-btn ids-btn-ghost" style={{ marginBottom: 20 }} onClick={() => navigate("orders")}>← Back to Orders</button>
 <SectionHeader title={`Order ${dv(order.number)}`}>
 <StatusBadge status={val(order.status)} />
 </SectionHeader>

 <div className="ids-card" style={{ marginBottom: 20 }}>
 <h3 className="ids-card-title">Order Information</h3>
 <div className="profile-grid">
 {fields.map(([label, value], i) => (
 <div className="profile-field" key={i}>
 <div className="profile-label">{label}</div>
 {label === "Status" ? <StatusBadge status={val(order.status)} /> : <div className="profile-value">{value}</div>}
 </div>
 ))}
 </div>
 </div>

 <div className="ids-card" style={{ padding: 0, overflow: "hidden" }}>
 <div style={{ padding: "18px 24px 14px", borderBottom: "1px solid var(--ids-border)" }}>
 <h3 style={{ margin: 0, fontSize: 15, fontWeight: 700 }}>Order Items ({items.length})</h3>
 </div>
 {items.length === 0 ? (
 <EmptyState icon="📋" title="No items" desc="This order has no line items." />
 ) : (
 <div style={{ overflowX: "auto" }}>
 <table className="ids-table">
 <thead><tr><th>Item #</th><th>Product</th><th>Qty</th><th>UOM</th><th>Status</th><th>Priority</th></tr></thead>
 <tbody>
 {items.map((it, i) => (
 <tr key={i}>
 <td style={{ fontWeight: 600 }}>{dv(it.number)}</td>
 <td>{dv(it.material_product)}</td>
 <td style={{ fontFamily: "var(--ids-font-mono)" }}>{dv(it.quantity_ordered)}</td>
 <td>{dv(it.unit_of_measure) || "—"}</td>
 <td><StatusBadge status={val(it.item_status)} /></td>
 <td>{dv(it.priority) || "—"}</td>
 </tr>
 ))}
 </tbody>
 </table>
 </div>
 )}
 </div>
 </div>
 );
}

/* ═══════════════════ DELIVERY ═══════════════════ */
function Delivery({ orders }: { orders: Rec[] }) {
 const activeOrders = orders.filter(o => {
 const s = val(o.status).toLowerCase();
 return s !== "completed" && s !== "cancelled" && s !== "draft";
 });

 return (
 <div className="portal-section">
 <SectionHeader title="Delivery Tracking" sub="Track delivery status of your active orders" />
 {activeOrders.length === 0 ? (
 <div className="ids-card">
 <EmptyState icon="🚚" title="No active deliveries" desc="Orders in progress will appear here with delivery tracking." />
 </div>
 ) : (
 <div className="delivery-list">
 {activeOrders.map((o, i) => {
 const dd = dv(o.requested_delivery_date);
 const days = dd ? daysUntil(dd) : null;
 let countdownText = "No date set";
 let countdownClass = "";
 if (days !== null) {
 if (days < 0) { countdownText = `${Math.abs(days)} day${Math.abs(days) !== 1 ? "s" : ""} overdue`; countdownClass = "countdown-overdue"; }
 else if (days === 0) { countdownText = "Due today"; countdownClass = "countdown-soon"; }
 else if (days <= 3) { countdownText = `in ${days} day${days !== 1 ? "s" : ""}`; countdownClass = "countdown-soon"; }
 else { countdownText = `in ${days} days`; countdownClass = "countdown-ok"; }
 }
 return (
 <div className="delivery-card" key={i}>
 <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
 <div>
 <div style={{ fontSize: 14, fontWeight: 600, color: "var(--ids-text-primary)" }}>{dv(o.number)}</div>
 <div style={{ fontSize: 12, color: "var(--ids-text-tertiary)", marginTop: 2 }}>
 Delivery: {dd ? fmtDate(dd) : "Not scheduled"}
 </div>
 </div>
 <StatusBadge status={val(o.status)} />
 </div>
 <div className={`countdown ${countdownClass}`}>{countdownText}</div>
 </div>
 );
 })}
 </div>
 )}
 </div>
 );
}

