 <table className="ids-table">
 <thead><tr><th>Material</th><th>Category</th><th>Safety Stock</th><th>UOM</th></tr></thead>
 <tbody>
 {products.filter(p => dv(p.safety_stock)).map((p, i) => (
 <tr key={i}>
 <td style={{ fontWeight: 600 }}>{dv(p.material_name)}</td>
 <td>{dv(p.category) || "—"}</td>
 <td style={{ fontFamily: "var(--ids-font-mono)", fontWeight: 600 }}>{dv(p.safety_stock)}</td>
 <td>{dv(p.unit_of_measure) || "—"}</td>
 </tr>
 ))}
 </tbody>
 </table>
 </div>
 </div>
 )}
 </div>
 );
}

/* ═══════════════════ SURVEYS ═══════════════════ */
function Surveys() {
 const [rating, setRating] = useState(0);
 const [comment, setComment] = useState("");
 const [submitting, setSubmitting] = useState(false);
 const [submitted, setSubmitted] = useState(false);
 const [configuring, setConfiguring] = useState(false);

 const handleSubmit = async () => {
 if (rating === 0) return;
 setSubmitting(true);
 const res = await apiPost(`/api/now/table/${SCOPE}_cust_survey`, {
 rating: rating.toString(),
 comments: comment,
 });
 setSubmitting(false);
 if (res?.result) {
 setSubmitted(true);
 } else {
 setConfiguring(true);
 }
 };

 if (submitted) {
 return (
 <div className="portal-section">
 <div className="ids-card">
 <div className="success-state">
 <div className="success-icon">✓</div>
 <div className="success-title">Thank You!</div>
 <div className="success-desc">Your feedback has been submitted. We appreciate you taking the time to help us improve.</div>
 </div>
 </div>
 </div>
 );
 }

 if (configuring) {
 return (
 <div className="portal-section">
 <SectionHeader title="Customer Survey" sub="Share your feedback" />
 <div className="ids-card">
 <div style={{ display: "flex", flexDirection: "column", alignItems: "center", padding: "40px 24px", textAlign: "center", gap: 12 }}>
 <div style={{ width: 56, height: 56, borderRadius: "var(--ids-radius-lg)", background: "var(--ids-info-bg)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 24 }}>🔧</div>
 <div style={{ fontSize: 17, fontWeight: 700 }}>Survey Submission Being Configured</div>
 <div style={{ fontSize: 14, color: "var(--ids-text-secondary)", maxWidth: 440, lineHeight: 1.5 }}>
 The survey submission system is currently being set up. Your feedback is important to us — please check back soon.
 </div>
 </div>
 </div>
 </div>
 );
 }

 return (
 <div className="portal-section">
 <SectionHeader title="Customer Survey" sub="We'd love to hear your feedback" />
 <div className="ids-card" style={{ maxWidth: 600 }}>
 <h3 className="ids-card-title">How would you rate your experience?</h3>
 <div className="rating-stars">
 {[1, 2, 3, 4, 5].map(n => (
 <button key={n} className={`star-btn${rating >= n ? " star-btn-filled" : ""}`} onClick={() => setRating(n)}>
 ★
 </button>
 ))}
 {rating > 0 && <span style={{ fontSize: 13, color: "var(--ids-text-secondary)", marginLeft: 8, alignSelf: "center" }}>{rating} / 5</span>}
 </div>
 <div style={{ marginBottom: 16 }}>
 <label style={{ display: "block", fontSize: 13, fontWeight: 600, color: "var(--ids-text-secondary)", marginBottom: 6 }}>Comments (optional)</label>
 <textarea className="order-form-input" style={{ width: "100%" }}
 placeholder="Share your thoughts, suggestions, or concerns…"
 value={comment} onChange={e => setComment(e.target.value)} />
 </div>
 <button className="ids-btn ids-btn-accent" onClick={handleSubmit} disabled={rating === 0 || submitting}>
 {submitting ? "Submitting…" : "Submit Feedback"}
 </button>
 </div>
 </div>
 );
}

