 {(dv(customer.customer_name) || "C").charAt(0).toUpperCase()}
 </div>
 <div>
 <div style={{ fontSize: 18, fontWeight: 700, color: "var(--ids-brand-navy)" }}>{dv(customer.customer_name)}</div>
