 </div>
 ))}
 </div>
 </div>
 </div>
 );
}

/* ═══════════════════ APP ROOT ═══════════════════ */
function App() {
 const [route, setRoute] = useState<Route>(parseHash);
 const [ctx, setCtx] = useState<CustCtx | null>(null);
 const [orders, setOrders] = useState<Rec[]>([]);
 const [orderItems, setOrderItems] = useState<Rec[]>([]);
 const [products, setProducts] = useState<Rec[]>([]);
 const [cart, setCart] = useState<CartItem[]>([]);
 const [loading, setLoading] = useState(true);

 /* ── Hash listener ── */
 useEffect(() => {
 const onHash = () => setRoute(parseHash());
 window.addEventListener("hashchange", onHash);
 return () => window.removeEventListener("hashchange", onHash);
 }, []);

 /* ── Load data: 2-phase (context first, then customer-scoped) ── */
 useEffect(() => {
 let m = true;
 (async () => {
 const [c, p] = await Promise.all([
 apiFetch<CustCtx>(API.context),
 apiFetch<Rec[]>(API.products),
 ]);
 if (!m) return;
 setProducts(Array.isArray(p) ? p : []);
 const resolved: CustCtx = c && typeof c.linked === "boolean" ? c : { linked: false, message: "Unable to resolve customer identity." };
 setCtx(resolved);
 if (resolved.linked && resolved.customer) {
 const cid = resolved.customer.sys_id;
 const [o, oi] = await Promise.all([
 apiFetch<Rec[]>(buildOrdersUrl(cid)),
 apiFetch<Rec[]>(buildItemsUrl(cid)),
 ]);
 if (!m) return;
 setOrders(Array.isArray(o) ? o : []);
 setOrderItems(Array.isArray(oi) ? oi : []);
 }
 setLoading(false);
 })();
 return () => { m = false; };
 }, []);

 /* ── Navigate ── */
 const navigate = useCallback((view: string, id?: string) => { setHash(view, id); }, []);

 /* ── Cart ops ── */
 const addToCart = useCallback((item: CartItem) => {
 setCart(prev => {
 const idx = prev.findIndex(c => c.productId === item.productId);
 if (idx >= 0) {
 const upd = [...prev];
 upd[idx] = { ...upd[idx], quantity: upd[idx].quantity + item.quantity };
 return upd;
 }
 return [...prev, item];
 });
 }, []);
 const updateQty = useCallback((i: number, q: number) => {
 setCart(prev => { const u = [...prev]; u[i] = { ...u[i], quantity: q }; return u; });
 }, []);
 const removeItem = useCallback((i: number) => {
 setCart(prev => prev.filter((_, idx) => idx !== i));
 }, []);
 const clearCart = useCallback(() => setCart([]), []);

 /* ── Derive active tab ── */
 const activeTab = route.view === "product" || route.view === "review" ? (route.view === "review" ? "cart" : "catalog")
 : route.view === "order" ? "orders"
 : route.view === "cart" ? "cart"
 : NAV_TABS.find(t => t.key === route.view) ? route.view : "dashboard";

 const isLinked = ctx?.linked === true;
 const customer: Rec | null = isLinked && ctx?.customer ? ctx.customer : null;
 const customerName = customer ? (customer.customer_name || "") : "";

 return (
 <div className="portal-shell">
 {/* ── Header ── */}
 <header className="portal-header">
 <div className="portal-header-top">
 <div className="portal-brand">
 <div className="portal-brand-icon">🏭</div>
 Industrial Supply Co.
 </div>
 <div className="portal-header-right">
 {customerName && <span className="portal-customer-name">Welcome, {customerName}</span>}
 <button className="portal-cart-btn" onClick={() => navigate("cart")}>
 🛒 Cart
 {cart.length > 0 && <span className="portal-cart-badge">{cart.reduce((s, c) => s + c.quantity, 0)}</span>}
 </button>
 </div>
 </div>
 <nav className="portal-nav">
 {NAV_TABS.map(t => (
 <button key={t.key}
 className={`portal-tab${activeTab === t.key ? " portal-tab-active" : ""}`}
 onClick={() => navigate(t.key)}>
 {t.label}
 </button>
 ))}
 </nav>
 </header>

 {/* ── Main Content ── */}
 <main className="portal-content">
 {loading ? <Loading msg="Loading portal…" /> : (
 <>
 {route.view === "dashboard" && (isLinked ? <Dashboard orders={orders} orderItems={orderItems} products={products} navigate={navigate} /> : <AccountNotLinked email={ctx?.userEmail} message={ctx?.message} />)}
 {route.view === "catalog" && <Catalog products={products} navigate={navigate} />}
 {route.view === "product" && route.id && <ProductDetail productId={route.id} products={products} addToCart={addToCart} navigate={navigate} />}
 {route.view === "cart" && <CartView cart={cart} updateQty={updateQty} removeItem={removeItem} navigate={navigate} />}
 {route.view === "review" && (isLinked ? <OrderReview cart={cart} customer={customer} clearCart={clearCart} navigate={navigate} /> : <AccountNotLinked email={ctx?.userEmail} message={ctx?.message} />)}
 {route.view === "orders" && (isLinked ? <MyOrders orders={orders} navigate={navigate} /> : <AccountNotLinked email={ctx?.userEmail} message={ctx?.message} />)}
 {route.view === "order" && route.id && (isLinked ? <OrderDetail orderId={route.id} orders={orders} orderItems={orderItems} navigate={navigate} /> : <AccountNotLinked email={ctx?.userEmail} message={ctx?.message} />)}
 {route.view === "delivery" && (isLinked ? <Delivery orders={orders} /> : <AccountNotLinked email={ctx?.userEmail} message={ctx?.message} />)}
 {route.view === "demand" && <DemandAvailability products={products} />}
 {route.view === "surveys" && <Surveys />}
 {route.view === "profile" && (isLinked ? <Profile customer={customer} /> : <AccountNotLinked email={ctx?.userEmail} message={ctx?.message} />)}
 </>
 )}
 </main>
 </div>
 );
}

